-- CHAMBA 045 — Agenda técnico con login teléfono (sin JWT obligatorio)-- Alinea get_worker_assignments con get_worker_open_jobs_feed (017):-- auth.uid() null → devuelve agenda si p_worker_id es técnico válido.-- auth.uid() presente → solo propio worker o admin (038).SET statement_timeout = '120s';CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_worker_assignments CASCADE;CREATE OR REPLACE FUNCTION get_worker_assignments(p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_result JSONB;BEGIN  IF p_worker_id IS NULL THEN    RETURN '[]'::jsonb;  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_worker_id AND p.role::text = 'worker'  ) THEN    RETURN '[]'::jsonb;  END IF;  IF auth.uid() IS NOT NULL AND auth.uid() <> p_worker_id THEN    IF NOT EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid() AND p.role::text = 'admin'    ) THEN      RETURN '[]'::jsonb;    END IF;  END IF;  SELECT COALESCE(    jsonb_agg(      jsonb_build_object(        'id', ja.id,        'job_id', ja.job_id,        'worker_id', ja.worker_id,        'assigned_at', ja.assigned_at,        'completed_at', ja.completed_at,        'payment_status', ja.payment_status,        'payment_intent_id', ja.payment_intent_id,        'selection_status', ja.selection_status,        'job', to_jsonb(j.*)      )      ORDER BY ja.assigned_at DESC    ),    '[]'::jsonb  )  INTO v_result  FROM job_assignments ja  JOIN jobs j ON j.id = ja.job_id  WHERE ja.worker_id = p_worker_id;  RETURN v_result;END;$$;GRANT EXECUTE ON FUNCTION get_worker_assignments(UUID) TO anon, authenticated;